import XCTest
@testable import BrailleTranslatorApp

final class BrailleTranslatorRegulationTests: XCTestCase {

    let translator = BrailleTranslator()

    private func assertCase(
        _ input: String,
        _ expected: [String],
        rule: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        let actual = translator.translate(input)
        XCTAssertEqual(
            actual, expected,
            "[\(rule)] '\(input)' — expected \(expected), got \(actual)",
            file: file, line: line
        )
    }

