        assertCase("그러나저러나", ["1", "14", "46", "234", "5", "234", "14"], rule: "제18항 [붙임]")  // ⠁⠉⠨⠎⠐⠎⠉
        assertCase("그러면서", ["1", "25", "6", "234"], rule: "제18항 [붙임]")  // ⠁⠒⠠⠎
        assertCase("그런데도", ["1", "1345", "24", "136"], rule: "제18항 [붙임]")  // ⠁⠝⠊⠥
        assertCase("그리하여도", ["1", "156", "24", "136"], rule: "제18항 [붙임]")  // ⠁⠱⠊⠥
        // NOTE: PDF의 "왜 그러나요?" 케이스는 공백+물음표 처리가 약어 규칙과 무관해 제외함
    }

    // MARK: - 제18항_다만_약어앞
    /// 약어 앞에 다른 글자 붙으면 약어 미사용
    func test_제18항_다만_약어앞다른글자() {
        assertCase("오그리고", ["136", "4", "246", "5", "135", "4", "136"], rule: "제18항 [다만]")  // ⠥⠈⠪⠐⠕⠈⠥
        assertCase("우그리고", ["134", "4", "246", "5", "135", "4", "136"], rule: "제18항 [다만]")  // ⠍⠈⠪⠐⠕⠈⠥
        assertCase("쭈그리고", ["6", "46", "134", "4", "246", "5", "135", "4", "136"], rule: "제18항 [다만]")  // ⠠⠨⠍⠈⠪⠐⠕⠈⠥
        assertCase("찡그리고", ["6", "46", "135", "2356", "4", "246", "5", "135", "4", "136"], rule: "제18항 [다만]")  // ⠠⠨⠕⠶⠈⠪⠐⠕⠈⠥
    }

}